<?php
 declare(strict_types=1); namespace Slim\Http\Factory; use Psr\Http\Message\ServerRequestFactoryInterface; use Psr\Http\Message\ServerRequestInterface; use Psr\Http\Message\UriInterface; use Slim\Http\ServerRequest; class DecoratedServerRequestFactory implements ServerRequestFactoryInterface { protected $serverRequestFactory; public function __construct(ServerRequestFactoryInterface $serverRequestFactory) { $this->serverRequestFactory = $serverRequestFactory; } public function createServerRequest(string $method, $uri, array $serverParams = []): ServerRequestInterface { $serverRequest = $this->serverRequestFactory->createServerRequest($method, $uri, $serverParams); return new ServerRequest($serverRequest); } } 